// Prepare document data for OCR processing
const body = $json.body || {};

// Determine document type and build appropriate prompt
const docType = body.document_type || 'unknown';
const clientId = body.client_id;
const documentUrl = body.document_url;
const ocrText = body.ocr_text || '';
const base64Image = body.base64_image || '';

let extractionPrompt = '';
let systemPrompt = '';

if (docType === 'id' || docType === 'passport') {
  systemPrompt = `You are a FICA document OCR expert for South African real estate compliance. Extract and validate ID document information with high accuracy.`;
  extractionPrompt = `Extract information from this South African ID document or Passport.

Document Type: ${docType}
${ocrText ? `OCR Text Extracted: ${ocrText}` : ''}
${base64Image ? 'Image: [Base64 image data provided]' : ''}

For ID Document or Passport, extract:
- full_name (exactly as shown)
- id_number (13-digit RSA ID or passport number)
- date_of_birth (YYYY-MM-DD format)
- nationality (e.g., South African, Zimbabwean, etc.)
- expiry_date (if shown, YYYY-MM-DD format)
- document_number (if passport)

Validate:
- Check if image/text is clear and readable
- Check if document appears expired
- Check if all required fields are present
- Flag any issues (blurry, cut off, glare, missing info)

Return JSON:
{
  "document_type": "id|passport",
  "extracted_data": {
    "full_name": "...",
    "id_number": "...",
    "date_of_birth": "YYYY-MM-DD",
    "nationality": "...",
    "expiry_date": "YYYY-MM-DD|null"
  },
  "validation": {
    "is_clear": true|false,
    "is_expired": true|false,
    "is_complete": true|false,
    "issues": ["list any problems"]
  },
  "confidence": 0.0-1.0
}`;
} else if (docType === 'utility_bill' || docType === 'bank_statement') {
  systemPrompt = `You are a FICA document OCR expert for South African real estate compliance. Extract and validate proof of address documents.`;
  extractionPrompt = `Extract information from this Proof of Address document (Utility Bill or Bank Statement).

Document Type: ${docType}
${ocrText ? `OCR Text Extracted: ${ocrText}` : ''}
${base64Image ? 'Image: [Base64 image data provided]' : ''}

For Proof of Address, extract:
- address_lines (full address as array of lines)
- utility_type (electricity|water|rates|bank_statement|telkom|other)
- bill_date (YYYY-MM-DD format)
- issuer (e.g., City of Johannesburg, Eskom, FNB, Standard Bank)
- account_number (if visible)
- statement_period (for bank statements: "MMM YYYY" or date range)

Validate:
- Check if image/text is clear and readable
- Check if document is not older than 3 months
- Check if all required fields are present
- Flag any issues (blurry, cut off, glare, missing info, outdated)

Return JSON:
{
  "document_type": "utility_bill|bank_statement",
  "extracted_data": {
    "address_lines": ["line1", "line2", "line3"],
    "utility_type": "electricity|water|bank_statement|...",
    "bill_date": "YYYY-MM-DD",
    "issuer": "...",
    "account_number": "..."
  },
  "validation": {
    "is_clear": true|false,
    "is_expired": true|false,
    "is_complete": true|false,
    "is_recent": true|false,
    "issues": ["list any problems"]
  },
  "confidence": 0.0-1.0
}`;
} else {
  systemPrompt = `You are a FICA document OCR expert.`;
  extractionPrompt = `Analyze this document and determine its type. Extract any identifiable information.

Document Type: ${docType}
${ocrText ? `OCR Text: ${ocrText}` : ''}
${base64Image ? 'Image: [Base64 image data provided]' : ''}

Return JSON:
{
  "document_type": "unknown|id|passport|utility_bill|bank_statement|other",
  "extracted_data": {},
  "validation": {
    "is_clear": true|false,
    "is_expired": false,
    "is_complete": false,
    "issues": ["unknown document type"]
  },
  "confidence": 0.0
}`;
}

return [{
  json: {
    client_id: clientId,
    document_type: docType,
    document_url: documentUrl,
    system_prompt: systemPrompt,
    extraction_prompt: extractionPrompt,
    has_image: !!base64Image,
    has_ocr_text: !!ocrText
  }
}];

// Parse Groq OCR response
const groqResponse = $json;
const promptData = $('Build Extraction Prompt').item.json;

// Extract content from Groq response
const content = groqResponse.choices?.[0]?.message?.content || '{}';

// Parse JSON response
let extractionResult;
try {
  // Handle both direct JSON and markdown-wrapped JSON
  const jsonMatch = content.match(/```json\s*([\s\S]*?)```/) || content.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : content;
  extractionResult = JSON.parse(jsonStr);
} catch (e) {
  // Fallback if JSON parsing fails
  extractionResult = {
    document_type: promptData.document_type,
    extracted_data: {},
    validation: {
      is_clear: false,
      is_expired: false,
      is_complete: false,
      issues: ['Failed to parse AI response: ' + e.message]
    },
    confidence: 0
  };
}

// Calculate derived fields
const validation = extractionResult.validation || {};
const issues = validation.issues || [];

// Determine overall status
let status = 'pending_review';
if (validation.is_complete && validation.is_clear && !validation.is_expired && issues.length === 0) {
  status = 'verified';
} else if (issues.some(i => i.toLowerCase().includes('expired'))) {
  status = 'rejected';
} else if (issues.some(i => i.toLowerCase().includes('blurry') || i.toLowerCase().includes('unclear'))) {
  status = 'requires_resubmission';
}

// Build final output
const output = {
  client_id: promptData.client_id,
  document_type: extractionResult.document_type || promptData.document_type,
  extracted_data: extractionResult.extracted_data || {},
  validation: {
    is_clear: validation.is_clear ?? false,
    is_expired: validation.is_expired ?? false,
    is_complete: validation.is_complete ?? false,
    is_recent: validation.is_recent ?? null,
    issues: issues
  },
  confidence: extractionResult.confidence || 0,
  document_url: promptData.document_url,
  status: status,
  processed_at: new Date().toISOString()
};

return [{
  json: output
}];
